import json
from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(1, 13))
    # Mix of uniform values and biased edge values (0, +-1, extremes, negatives).
    pool = st.sampled_from([-9, -8, -5, -2, -1, 0, 1, 2, 5, 8, 9])
    nums = draw(st.lists(st.one_of(st.integers(-9, 9), pool), min_size=n, max_size=n))
    return json.dumps(nums)

def validate(inp):
    try:
        lines = inp.strip().split("\n")
        if len(lines) != 1:
            return False
        nums = json.loads(lines[0])
    except Exception:
        return False
    if not isinstance(nums, list):
        return False
    if not (1 <= len(nums) <= 13):
        return False
    for x in nums:
        if type(x) is not int:
            return False
        if not (-9 <= x <= 9):
            return False
    return True

def ref(inp):
    nums = json.loads(inp.strip())
    n = len(nums)
    best = None
    # Literal definition: try every non-empty subset of indices.
    for mask in range(1, 1 << n):
        prod = 1
        for i in range(n):
            if mask >> i & 1:
                prod *= nums[i]
        if best is None or prod > best:
            best = prod
    return json.dumps(best)
